window.HOEREN_TESTS[95] = {"id":"im-blumenladen","name":"Im Blumenladen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist der Blumenladen Rosengarten. Ihr bestellter Strauß für die Hochzeit ist fertig. Aber wir hatten keine weißen Rosen mehr, deshalb haben wir cremefarbene genommen, die passen sehr gut. Zu teuer waren die weißen nicht, es gab einfach keine mehr. Sie können ihn am Samstag ab 9 Uhr abholen. Bis dann, auf Wiederhören!","gender":"f","q":"Warum sind die Rosen nicht weiß?","opts":["Es gab keine weißen mehr.","Sie waren zu teuer.","Die Kundin wollte cremefarbene."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Du, ich habe Streit mit meiner Freundin und will mich entschuldigen. Ich gehe in den Blumenladen und kaufe ihr Blumen. Aber welche? Rote Rosen sind vielleicht zu viel. Du kennst dich aus mit Frauen. Was meinst du? Ruf schnell zurück, ich stehe schon im Laden!","gender":"m","q":"Warum kauft Markus Blumen?","opts":["Zum Geburtstag.","Für eine Hochzeit.","Um sich zu entschuldigen."],"correct":2},{"transcript":"Achtung Kunden: Wir liefern Blumen jetzt auch nach Hause, in der ganzen Stadt. Bestellen Sie telefonisch oder im Internet. Die Lieferung am selben Tag kostet 6 Euro. Für einen Geburtstag oder als Überraschung ist das ideal. Auch eine Karte mit Ihrem Gruß legen wir gern dazu. Fragen Sie uns!","gender":"m","q":"Was bietet der Laden jetzt an?","opts":["Blumen pflanzen.","Blumen nach Hause liefern.","Blumen verleihen."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Ich habe mir Blumen für den Balkon gekauft, so schöne bunte! Die Verkäuferin hat mir genau erklärt, wie oft ich sie gießen muss und wo sie stehen sollen — nicht in der prallen Sonne. Ich freue mich schon. Du wolltest doch auch deinen Balkon bepflanzen. Bis bald!","gender":"f","q":"Wofür hat Anna Blumen gekauft?","opts":["Für den Balkon.","Für eine Feier.","Als Geschenk."],"correct":0},{"transcript":"Liebe Kunden: Zum Muttertag empfehlen wir, früh zu bestellen. An diesem Tag ist immer sehr viel los, und beliebte Blumen sind schnell aus. Wer einen besonderen Strauß möchte, gibt ihn besser zwei Tage vorher in Auftrag. Auch Topfpflanzen sind ein schönes Geschenk. Wir freuen uns auf Sie!","gender":"f","q":"Was empfiehlt der Laden zum Muttertag?","opts":["Keine Rosen zu kaufen.","Erst am Muttertag zu kommen.","Früh zu bestellen."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft Blumen wofür? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Laden ist voll mit Blumen. Für wen kaufen wir heute?"},{"speaker":"Lisa","gender":"f","text":"Ich habe fünf Namen auf dem Zettel. Jeder braucht etwas anderes."},{"speaker":"Lukas","gender":"m","text":"Ich kaufe Blumen für eine Hochzeit. Wir brauchen viele weiße Rosen."},{"speaker":"Lisa","gender":"f","text":"Die liegen im kühlen Raum. Kauft jemand Blumen für die Wohnung?"},{"speaker":"Lukas","gender":"m","text":"Für die Wohnung kauft hier keiner. Zu Hause stehen schon genug."},{"speaker":"Lisa","gender":"f","text":"Ich kaufe Blumen für einen Geburtstag."},{"speaker":"Lukas","gender":"m","text":"Bunt passt gut dazu. Wie alt wird deine Freundin?"},{"speaker":"Lisa","gender":"f","text":"Sie wird dreißig. Tom kauft Topfpflanzen für den Balkon."},{"speaker":"Lukas","gender":"m","text":"Drei grüne Töpfe sollen in die Sonne. Nimmt jemand etwas zum Muttertag?"},{"speaker":"Lisa","gender":"f","text":"Zum Muttertag nimmt auch keiner etwas. Der war erst im Mai."},{"speaker":"Lukas","gender":"m","text":"Die Töpfe stehen rechts. Sara will einer Freundin danken und sucht etwas Nettes."},{"speaker":"Lisa","gender":"f","text":"Sara will sich mit den Blumen bedanken. Sie nimmt die gelben."},{"speaker":"Lukas","gender":"m","text":"Tim fährt am Sonntag zu einem ruhigen Ort. Er kauft Blumen für ein Grab."},{"speaker":"Lisa","gender":"f","text":"Er will weiße und er bleibt dort nicht lang."},{"speaker":"Lukas","gender":"m","text":"Danach fährt er wieder nach Hause."},{"speaker":"Lisa","gender":"f","text":"Ich zahle an der Kasse."}],"options":[{"letter":"a","text":"Für eine Hochzeit"},{"letter":"b","text":"Für ein Grab"},{"letter":"c","text":"Für einen Geburtstag"},{"letter":"d","text":"Für die Wohnung"},{"letter":"e","text":"Zur Entschuldigung"},{"letter":"f","text":"Topfpflanzen für den Balkon"},{"letter":"g","text":"Für eine Beerdigung"},{"letter":"h","text":"Zum Muttertag"},{"letter":"i","text":"Um sich zu bedanken"}],"items":[{"person":"Lukas","correct":"a"},{"person":"Lisa","correct":"c"},{"person":"Tom","correct":"f"},{"person":"Sara","correct":"i"},{"person":"Tim","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Was kostet ein bunter Strauß? 15 Euro, 25 oder schon 35?"},{"speaker":"Floristin","gender":"f","text":"Ab 15 Euro, je nach Größe. 35 Euro wäre ein sehr großer Strauß. Wunderschön."},{"speaker":"Kundin","gender":"f","text":"Einen schönen großen, bitte. 25 oder 35?"},{"speaker":"Floristin","gender":"f","text":"Dann nehmen wir den für 25 Euro. Nicht 15 und nicht 35, 25 Euro ist ein schöner großer Strauß."},{"speaker":"Kundin","gender":"f","text":"Perfekt, dann 25 Euro. Danke schön!"}],"q":"Was kostet der große Strauß?","opts":["15 Euro.","25 Euro.","35 Euro."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Welche Blumen halten lange? Rosen, Tulpen und Nelken, oder keine?"},{"speaker":"Florist","gender":"m","text":"Tulpen und Nelken halten gut. Rosen halten kürzer."},{"speaker":"Mann","gender":"m","text":"Und Rosen? Halten die so lang wie Tulpen und Nelken?"},{"speaker":"Florist","gender":"m","text":"Die halten leider nicht so lange. Also Tulpen und Nelken, nicht Rosen."},{"speaker":"Mann","gender":"m","text":"Dann Tulpen und Nelken, bitte. Danke."}],"q":"Welche Blumen halten laut dem Floristen lange?","opts":["Rosen.","Keine.","Tulpen und Nelken."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Können Sie eine Karte dazulegen? Zum Geburtstag, zur Hochzeit oder gute Besserung?"},{"speaker":"Floristin","gender":"f","text":"Gern. Was soll draufstehen? Hochzeit und gute Besserung gehen auch."},{"speaker":"Frau","gender":"f","text":"Alles Gute zum Geburtstag. Nicht zur Hochzeit und nicht gute Besserung."},{"speaker":"Floristin","gender":"f","text":"Mache ich, kein Problem. Alles Gute zum Geburtstag, nicht zur Hochzeit, nicht gute Besserung."},{"speaker":"Frau","gender":"f","text":"Danke, das reicht. Nur der Geburtstagstext."}],"q":"Was soll auf der Karte stehen?","opts":["Alles Gute zum Geburtstag.","Herzlichen Glückwunsch zur Hochzeit.","Gute Besserung."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Liefern Sie auch heute noch? Oder erst morgen, oder übermorgen?"},{"speaker":"Florist","gender":"m","text":"Ja, bis 17 Uhr bestellt, heute geliefert. Morgen und übermorgen gehen auch, aber heute klappt es oft."},{"speaker":"Kunde","gender":"m","text":"Es ist jetzt 16 Uhr. Also noch heute, nicht morgen?"},{"speaker":"Florist","gender":"m","text":"Dann klappt es noch heute. Nicht morgen und nicht übermorgen, noch heute."},{"speaker":"Kunde","gender":"m","text":"Super, dann bitte noch heute liefern. Danke."}],"q":"Wann wird geliefert?","opts":["Morgen.","Noch heute.","Übermorgen."],"correct":1},{"lines":[{"speaker":"Kundin","gender":"f","text":"Wie oft muss ich diese Pflanze gießen? Jeden Tag, zweimal die Woche oder einmal im Monat?"},{"speaker":"Floristin","gender":"f","text":"Zweimal die Woche reicht. Jeden Tag wäre zu viel, einmal im Monat zu wenig."},{"speaker":"Kundin","gender":"f","text":"Und in die Sonne? Also nicht jeden Tag gießen?"},{"speaker":"Floristin","gender":"f","text":"Nein, lieber an einen hellen Platz ohne pralle Sonne. Gießen Sie zweimal die Woche, nicht jeden Tag, nicht einmal im Monat."},{"speaker":"Kundin","gender":"f","text":"Gut, zweimal die Woche. Danke für den Tipp."}],"q":"Wie oft soll die Kundin die Pflanze gießen?","opts":["Zweimal die Woche.","Jeden Tag.","Einmal im Monat."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Blum, einer Floristin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Blum, wann haben Sie am meisten zu tun im Laden?"},{"speaker":"Blum","gender":"f","text":"Am Valentinstag, am Muttertag und an Weihnachten. Dann ist sehr viel los. Am Muttertag habe ich besonders viel zu tun, das Geschäft ist voll."},{"speaker":"Reporter","gender":"m","text":"Was soll man beim Blumenkauf beachten, zum Beispiel die Jahreszeit?"},{"speaker":"Blum","gender":"f","text":"Kaufen Sie Blumen der Jahreszeit. Sie sind frischer und halten länger. Das rate ich immer, Blumen der Jahreszeit sind die beste Wahl."},{"speaker":"Reporter","gender":"m","text":"Verschenken Männer und Frauen andere Blumen? Kaufen Männer oft rote Rosen?"},{"speaker":"Blum","gender":"f","text":"Ein bisschen. Männer kaufen oft rote Rosen, Frauen lieber bunte Sträuße. Das sehe ich fast jedes Wochenende."},{"speaker":"Reporter","gender":"m","text":"Ist Ihr Beruf anstrengend, oder gar nicht?"},{"speaker":"Blum","gender":"f","text":"Ja, schon. Ich stehe früh auf und trage schwere Eimer mit Wasser. Der Beruf ist anstrengend, nicht leicht, aber ich mache ihn gern."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schönste an Ihrem Beruf? Finden Sie ihn schön?"},{"speaker":"Blum","gender":"f","text":"Ich mache die Menschen glücklich. Mit Blumen kann man Danke sagen. Ich finde meinen Beruf sehr schön, das ist der Grund, warum ich bleibe."}],"items":[{"q":"Frau Blum sagt, ihr Beruf ist gar nicht anstrengend.","correct":"nein"},{"q":"Am Muttertag hat sie besonders viel zu tun.","correct":"ja"},{"q":"Sie rät, Blumen der Jahreszeit zu kaufen.","correct":"ja"},{"q":"Männer kaufen oft rote Rosen.","correct":"ja"},{"q":"Sie findet ihren Beruf nicht schön.","correct":"nein"}]}]};
